window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-020a67994f506228"]={"versions": [{"id": "FIG-020a67994f506228", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation der Funktion <code>E2E_P04Forward()</code> im Kontext des AUTOSAR E2E-Protokolls (Profile 4). Dargestellt ist der Teilschritt „Verify inputs of the forward function“, der der Eingangsprüfung von Parametern vor der eigentlichen Weiterleitungs- und Schutzlogik dient.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Funktion / Aktivität</strong>: <code>E2E_P04Forward()</code></li>\n<li><strong>Eingangsparameter / Entitäten</strong>:</li>\n<li><code>Config</code>: Zeiger auf die Konfigurationsstruktur des E2E-Profils 4 (Prüfung gegen <code>NULL</code> sowie Längenprüfung gegen Konfigurationsgrenzen).</li>\n<li><code>State</code>: Zeiger auf die Zustandsstruktur der Weiterleitungsfunktion (Prüfung gegen <code>NULL</code>).</li>\n<li><code>Data</code>: Zeiger auf den Nutzdatenpuffer (Prüfung gegen <code>NULL</code>).</li>\n<li><code>ForwardStatus</code>: Statusparameter bzw. Zeiger auf den Weiterleitungsstatus (Prüfung gegen <code>NULL</code> sowie Plausibilisierung gegen ungültige Werte).</li>\n<li><code>Length</code>: Datenlängenwert zur Validierung anhand von Min-/Max-Grenzen in <code>Config</code>.</li>\n<li><strong>Knoten & Verzweigungen</strong>:</li>\n<li>Startknoten (Initial Node).</li>\n<li>Entscheidungsknoten 1: Prüfung der Zeigergültigkeit aller Pflichtparameter.</li>\n<li>Entscheidungsknoten 2: Prüfung der Datenlänge (<code>Length &gt;= Config-&gt;MinDataLength</code> && <code>Length &lt;= Config-&gt;MaxDataLength</code>) und des Eingangsstatus (<code>ForwardStatus != ...</code>).</li>\n<li>Drei Aktivitätsendknoten (Activity Final Nodes) für die Resultate: <code>null</code> (Null-Pointer-Fehler), <code>wrong</code> (ungültige Eingabewerte / Längenfehler) und Fortsetzung bzw. Akzeptanz (<code>input</code> / reguläre Weiterleitung).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Beginn am initialen Startknoten beim Aufruf von <code>E2E_P04Forward()</code>.</li>\n<li>Erste Verzweigung: Evaluierung der Bedingung <code>(Config != NULL) &amp;&amp; (State != NULL) &amp;&amp; (Data != NULL) &amp;&amp; (ForwardStatus != NULL)</code>.</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ergibt die Bedingung <code>[FALSE]</code>, zweigt der Kontrollfluss direkt zum Endknoten <code>null</code> ab.</li>\n<li>Ergibt die Bedingung <code>[TRUE]</code>, geht der Kontrollfluss zum zweiten Entscheidungsknoten über.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Zweite Verzweigung: Evaluierung der Längengrenzen und Statuswerte (<code>(Length &gt;= Config-&gt;...) &amp;&amp; (Length &lt;= Config-&gt;...) &amp;&amp; ForwardStatus != ...</code>).</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ergibt die Bedingung <code>[FALSE]</code>, zweigt der Ablauf nach rechts zum Endknoten <code>wrong</code> ab.</li>\n<li>Ergibt die Bedingung <code>[TRUE]</code>, mündet der Ablauf in den Endknoten <code>input</code> zur nachfolgenden Weiterleitungsverarbeitung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Prüfschritte sind normativ bindend für die Implementierung der Funktion <code>E2E_P04Forward()</code>. Implementierungen müssen vor jedem Zugriff auf Datenpuffer oder Konfigurationsstrukturen zwingend die Pointer auf <code>NULL</code> prüfen und bei Verletzung mit dem Fehlercode für ungültige Zeiger (<code>E2E_E_INPUTERR_NULL</code>) abbrechen. Ebenso sind Längen- und Statusprüfungen strikt vor der Weiterleitung durchzuführen; verletzte Werte führen zum Fehlerstatus für fehlerhafte Parameter (<code>E2E_E_INPUTERR_WRONG</code>). Erst nach erfolgreichem Durchlaufen beider Schutzabfragen darf der Nutzdatenstrom weiterverarbeitet werden.</p>"}, {"id": "FIG-a73437033418a1d7", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation der Funktion <code>E2E_P04Forward()</code> im Kontext des AUTOSAR E2E-Protokolls (Profile 4). Dargestellt ist der Teilschritt „Verify inputs of the forward function“, der der Eingangsprüfung von Parametern vor der eigentlichen Weiterleitungs- und Schutzlogik dient.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Funktion / Aktivität</strong>: <code>E2E_P04Forward()</code></li>\n<li><strong>Eingangsparameter / Entitäten</strong>:</li>\n<li><code>Config</code>: Zeiger auf die Konfigurationsstruktur des E2E-Profils 4 (Prüfung gegen <code>NULL</code> sowie Längenprüfung gegen Konfigurationsgrenzen).</li>\n<li><code>State</code>: Zeiger auf die Zustandsstruktur der Weiterleitungsfunktion (Prüfung gegen <code>NULL</code>).</li>\n<li><code>Data</code>: Zeiger auf den Nutzdatenpuffer (Prüfung gegen <code>NULL</code>).</li>\n<li><code>ForwardStatus</code>: Statusparameter bzw. Zeiger auf den Weiterleitungsstatus (Prüfung gegen <code>NULL</code> sowie Plausibilisierung gegen ungültige Werte).</li>\n<li><code>Length</code>: Datenlängenwert zur Validierung anhand von Min-/Max-Grenzen in <code>Config</code>.</li>\n<li><strong>Knoten & Verzweigungen</strong>:</li>\n<li>Startknoten (Initial Node).</li>\n<li>Entscheidungsknoten 1: Prüfung der Zeigergültigkeit aller Pflichtparameter.</li>\n<li>Entscheidungsknoten 2: Prüfung der Datenlänge (<code>Length &gt;= Config-&gt;MinDataLength</code> && <code>Length &lt;= Config-&gt;MaxDataLength</code>) und des Eingangsstatus (<code>ForwardStatus != ...</code>).</li>\n<li>Drei Aktivitätsendknoten (Activity Final Nodes) für die Resultate: <code>null</code> (Null-Pointer-Fehler), <code>wrong</code> (ungültige Eingabewerte / Längenfehler) und Fortsetzung bzw. Akzeptanz (<code>input</code> / reguläre Weiterleitung).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Beginn am initialen Startknoten beim Aufruf von <code>E2E_P04Forward()</code>.</li>\n<li>Erste Verzweigung: Evaluierung der Bedingung <code>(Config != NULL) &amp;&amp; (State != NULL) &amp;&amp; (Data != NULL) &amp;&amp; (ForwardStatus != NULL)</code>.</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ergibt die Bedingung <code>[FALSE]</code>, zweigt der Kontrollfluss direkt zum Endknoten <code>null</code> ab.</li>\n<li>Ergibt die Bedingung <code>[TRUE]</code>, geht der Kontrollfluss zum zweiten Entscheidungsknoten über.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Zweite Verzweigung: Evaluierung der Längengrenzen und Statuswerte (<code>(Length &gt;= Config-&gt;...) &amp;&amp; (Length &lt;= Config-&gt;...) &amp;&amp; ForwardStatus != ...</code>).</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ergibt die Bedingung <code>[FALSE]</code>, zweigt der Ablauf nach rechts zum Endknoten <code>wrong</code> ab.</li>\n<li>Ergibt die Bedingung <code>[TRUE]</code>, mündet der Ablauf in den Endknoten <code>input</code> zur nachfolgenden Weiterleitungsverarbeitung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Prüfschritte sind normativ bindend für die Implementierung der Funktion <code>E2E_P04Forward()</code>. Implementierungen müssen vor jedem Zugriff auf Datenpuffer oder Konfigurationsstrukturen zwingend die Pointer auf <code>NULL</code> prüfen und bei Verletzung mit dem Fehlercode für ungültige Zeiger (<code>E2E_E_INPUTERR_NULL</code>) abbrechen. Ebenso sind Längen- und Statusprüfungen strikt vor der Weiterleitung durchzuführen; verletzte Werte führen zum Fehlerstatus für fehlerhafte Parameter (<code>E2E_E_INPUTERR_WRONG</code>). Erst nach erfolgreichem Durchlaufen beider Schutzabfragen darf der Nutzdatenstrom weiterverarbeitet werden.</p>"}], "trans": [{"from": "FIG-020a67994f506228", "to": "FIG-a73437033418a1d7", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
